import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_RESERVA, MODELO_HOTEL } from '../../models/hotel-reserva.model.mjs';

export async function buscarHotelRepository(hotelId) {
  const { Item } = await MODELO_HOTEL.build(EntityRepository).get(
    { hotelId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarHotelRepository(hotelId, minimo) {
  const { Items = [] } = await MODELO_RESERVA.build(EntityRepository).query(
    { index: 'PorHotel', partition: hotelId },
    { filters: { Reserva: { attr: 'noches', gte: minimo } } }
  );
  return Items;
}

import { trasladarReservaService } from './service.mjs';

export async function handler(event) {
  const reservaId = Number(event.pathParameters.reservaId);
  const { hotelId } = JSON.parse(event.body);
  const resultado = await trasladarReservaService(reservaId, hotelId);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { trasladarReservaRepository } from './repository.mjs';
import { buscarHotelRepository } from '../../hoteles/consultar/repository.mjs';

export async function trasladarReservaService(reservaId, hotelId) {
  const hotel = await buscarHotelRepository(hotelId);
  if (!hotel) throw new Error('Hotel no encontrado');
  return trasladarReservaRepository(reservaId, hotelId);
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_RESERVA, MODELO_HOTEL } from '../../models/hotel-reserva.model.mjs';

export async function trasladarReservaRepository(reservaId, hotelId) {
  const { Attributes } = await MODELO_RESERVA.build(EntityRepository).update(
    { reservaId, hotelId },
    {
      condition: { attr: 'reservaId', exists: true },
      returnValues: 'ALL_NEW'
    }
  );
  return Attributes;
}

import { consultarHotelService } from './service.mjs';

export async function handler(event) {
  const hotelId = Number(event.pathParameters.hotelId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarHotelService(hotelId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarHotelRepository, consultarHotelRepository } from './repository.mjs';

export async function consultarHotelService(hotelId, minimo) {
  const hotel = await buscarHotelRepository(hotelId);
  if (!hotel) throw new Error('Hotel no encontrado');
  const reservas = await consultarHotelRepository(hotelId, minimo);
  return { hotel, reservas };
}

